import yaml, re, statistics
from collections import defaultdict

with open('registry.yaml', 'r') as f:
    reg = yaml.safe_load(f)

exps = reg.get('experiments', {})

def parse_epsilon(eid):
    mapping = {'003': 0.03, '005': 0.05, '01': 0.1, '02': 0.2}
    m = re.search(r'norm(\d+)', eid)
    if m:
        val = m.group(1)
        return mapping.get(val)
    return None

results = []
for eid, e in exps.items():
    if e.get('conclusion') != 'success':
        continue
    metrics = e.get('metrics', {})
    if not metrics or 'overall_success_rate' not in metrics:
        continue
    if 'obs_only' not in eid and 'obs-only' not in eid:
        continue
    if 'object' not in eid:
        continue
    if 'k5' in eid or 'spatial' in eid:
        continue

    eps = parse_epsilon(eid)
    if eps is None or eps not in [0.03, 0.05, 0.1, 0.2]:
        continue

    sr = metrics['overall_success_rate']
    seed_m = re.search(r'seed(\d+)', eid)
    seed = int(seed_m.group(1)) if seed_m else None
    # Detect retry suffix
    retry_m = re.search(r'-(r\d+|bjb\d)', eid)
    is_retry = bool(retry_m)
    results.append({'exp_id': eid, 'epsilon': eps, 'sr': sr, 'seed': seed, 'is_retry': is_retry})

# Deduplicate: for same (eps, seed), keep latest run (retry > original)
dedup = {}
for r in results:
    key = (r['epsilon'], r['seed'])
    if key not in dedup or r['is_retry']:
        dedup[key] = r

# Group by epsilon
grouped = defaultdict(list)
for (eps, seed), r in sorted(dedup.items()):
    grouped[eps].append(r['sr'])

print('=== Deduplicated norm sweep data ===')
for eps in sorted(grouped.keys()):
    vals = grouped[eps]
    mean = statistics.mean(vals)
    std = statistics.stdev(vals) if len(vals) > 1 else 0
    se = std / len(vals)**0.5 if len(vals) > 1 else 0
    print(f'eps={eps:.2f}: n={len(vals)}, mean={mean:.4f}, std={std:.4f}, se={se:.4f}')
    print(f'  values={[round(v,4) for v in vals]}')

# Also get VLA-only baseline for reference
vla_only_srs = []
for eid, e in exps.items():
    if e.get('conclusion') != 'success':
        continue
    metrics = e.get('metrics', {})
    if not metrics or 'overall_success_rate' not in metrics:
        continue
    if 'vla-only' not in eid and 'vla_only' not in eid:
        continue
    if 'object' not in eid:
        continue
    if 'k5' in eid or 'spatial' in eid or 'goal' in eid or 'openvla' in eid or 'pi05' in eid:
        continue
    sr = metrics['overall_success_rate']
    vla_only_srs.append(sr)

if vla_only_srs:
    print(f'\nVLA-only baseline: n={len(vla_only_srs)}, mean={statistics.mean(vla_only_srs):.4f}, values={vla_only_srs}')
